#include <vector>
#include <string>
#include <unordered_map>

class Solution {
public:
    int countWords(std::vector<std::string>& words1, std::vector<std::string>& words2) {
        std::unordered_map<std::string, int> c1, c2;
        for (const auto& w : words1) c1[w]++;
        for (const auto& w : words2) c2[w]++;

        int ans = 0;
        for (const auto& [w, cnt] : c1) {
            if (cnt == 1 && c2[w] == 1) {
                ans++;
            }
        }
        return ans;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int countWords(String[] words1, String[] words2) {
        Map<String, Integer> c1 = new HashMap<>();
        Map<String, Integer> c2 = new HashMap<>();

        for (String w : words1) c1.put(w, c1.getOrDefault(w, 0) + 1);
        for (String w : words2) c2.put(w, c2.getOrDefault(w, 0) + 1);

        int ans = 0;
        for (Map.Entry<String, Integer> entry : c1.entrySet()) {
            if (entry.getValue() == 1 && c2.getOrDefault(entry.getKey(), 0) == 1) {
                ans++;
            }
        }
        return ans;
    }
}

/**
 * @param {string[]} words1
 * @param {string[]} words2
